Given n elements and the task is to implement a stack which removes and returns the maximum frequency element on every pop operation. If there's a tie in the frequency then the topmost highest frequency element will be returned.Examples:  Input: push(4) 8 push(6) 6 push(7) 7 push(6) 6 push(8); 4Output: pop() -> returns 6, as 6 is the most frequent (frequency of 6 = 2 ). pop() -> returns 8 (6 also has the highest frequency but it is not the topmost)  Naive Approach - Priority Queue and Hash Map The idea is to use priority queue to order elements by frequency and a hash map to store frequencies of items. push(x) :  We increment frequency in map and insert new frequency in the priority queue. pop():  We pop the top item from priority queue (which is the max frequency item).
            C++

    #include <bits/stdc++.h>
using namespace std;

priority_queue<pair<int, pair<int, int> > > q;
unordered_map<int, int> freq;
int pos = 0;

void push(int x)
{
    ++freq[x];
    q.emplace(freq[x], make_pair(pos, x));
    ++pos;
}

int pop()
{
    auto val = q.top();
    q.pop();
    int x = val.second.second;
    freq[x]--;
    return x;
}

int main()
{
    push(4);
    push(6);
    push(7);
    push(6);
    push(8);

    cout << (pop()) << "\n";
    cout << (pop());

    return 0;
}


            Java

    import java.util.PriorityQueue;
import java.util.HashMap;

public class Main {

    // PriorityQueue to store elements in ascending order of their frequency
    // Each element of PriorityQueue is a triple of (-frequency, -position, value)
    static PriorityQueue<int[]> q = new PriorityQueue<>(
            (a, b) -> {
                if (a[0] != b[0]) {
                    return Integer.compare(a[0], b[0]);
                }
                if (a[1] != b[1]) {
                    return Integer.compare(a[1], b[1]);
                }
                return Integer.compare(a[2], b[2]);
            }
    );

    // HashMap to store the frequency of each element
    static HashMap<Integer, Integer> freq = new HashMap<>();
    static int pos = 0;

    // Function to push an element into PriorityQueue and update its frequency
    static void push(int x) {

        // Push a triple of (-frequency, -position, value) into PriorityQueue
        q.offer(new int[]{-freq.getOrDefault(x, 0), -pos, x});

        // Increment the frequency of element x in HashMap
        freq.put(x, freq.getOrDefault(x, 0) + 1);

        // Increment the position
        pos++;
    }

    // Function to remove an element from PriorityQueue and update its frequency
    static int pop() {

        // Remove the top element from PriorityQueue
        int[] val = q.poll();

        // Get the value of the removed element
        int x = val[2];

        // Decrement the frequency of element x in HashMap
        freq.put(x, freq.get(x) - 1);

        return x;
    }

    public static void main(String[] args) {
        push(4);
        push(6);
        push(7);
        push(6);
        push(8);
        System.out.println(pop());
        System.out.println(pop());
    }
}


